# ContextManager：核心类，封装了系统的关键行为和状态
class ContextManager:
    # build：公开方法，实现核心业务逻辑
    def build(self, diff, assignment=None, memories=()) -> ContextBundle:
        original_tokens = self.estimate_tokens(diff)
        available_tokens = self.max_tokens - self.reserved_tokens
        if original_tokens <= available_tokens:
            return ContextBundle(diff, False, ...)  # 不需要压缩

        # 1. 按风险评分排序所有 hunk
        terms = self._priority_terms(assignment, memories)
        file_headers, hunks = self._parse(diff, terms)
        # 2. 贪心选择：高分 hunk 优先装入预算
        for hunk in sorted(hunks, key=lambda h: (-h.score, h.index)):
            if used + hunk_cost <= byte_budget:
                selected.append(hunk)
            else:
                compact = self._compact_hunk(hunk, remaining, terms)
                if compact: selected.append(compact)
        # 3. 按原始顺序重组
        return ContextBundle(compressed, True, original_tokens, final_tokens,
                            omitted_files=omitted, strategy="risk-ranked-hunk-compression")

@staticmethod
# _score：内部辅助方法，供类内部其他方法调用
def _score(path, text, terms):
    score = sum(2.0 for term in terms if term and term in lowered)  # 风险词命中
    score += min(8.0, sum(1 for line in text.splitlines()
                         if line.startswith("+") and not line.startswith("+++")) * 0.25)
    if any(token in path.lower() for token in ("auth", "security", "payment", "migration")):
        score += 6.0  # 敏感文件路径加分
    return score
